//! Milestone 2.5: the image-to-font flow with `font_from_image`, through
//! MCP with the `image-font` profile, in both protocol eras, and the same
//! operation from the command line giving the same glyphs. The image is our
//! own specimen (generated by code; no third-party material).

mod mcp_common;

use std::process::Command;
use std::time::Duration;

use mcp_common::{
    call, close, connect, copy_specimen, forma_bin, legacy, modern, path_text, with_timeout_for,
};
use rmcp::ClientLifecycleMode;
use rstest::rstest;
use serde_json::{Value, json};

#[rstest]
#[case::legacy(legacy())]
#[case::modern(modern())]
#[tokio::test]
async fn scenario_b_both_protocol_eras(#[case] mode: ClientLifecycleMode) {
    with_timeout_for("scenario_b", Duration::from_secs(180), scenario(mode)).await;
}

async fn scenario(mode: ClientLifecycleMode) {
    let (client, root) = connect(mode, &["--profile", "image-font"]).await;
    let root = root.path();
    let image = copy_specimen(root, "specimen.png");
    let mut text_bytes = 0usize;
    let mut calls = 0usize;
    let mut count = |v: &Value| {
        calls += 1;
        text_bytes += serde_json::to_string(v).map_or(0, |t| t.len());
    };

    let created = call(
        &client,
        "document_create",
        json!({ "family_name": "Specimen" }),
    )
    .await
    .ok();
    count(&created);
    let doc = created["doc"].as_str().expect("doc").to_owned();
    let rev = created["rev"].as_u64().unwrap_or(0);
    let layout = json!(["ABCH", "OFMR"]);

    let planned = call(
        &client,
        "font_from_image",
        json!({ "doc": doc, "base_rev": rev, "path": image, "layout": layout, "dry_run": true }),
    )
    .await
    .ok();
    count(&planned);
    assert!(
        planned["plan"].is_object() && planned["stages"].is_array(),
        "{planned}"
    );

    let done = call(
        &client,
        "plan_commit",
        json!({ "plan_token": planned["plan"]["plan_token"] }),
    )
    .await
    .ok();
    count(&done);
    assert_eq!(done["stages"][0]["counts"]["glyphs"], 8, "{done}");
    let rev = done["rev"].as_u64().expect("rev");

    // Everything the engine made waits for review, in one sheet.
    let sheet = call(
        &client,
        "preview_sheet",
        json!({ "doc": doc, "filter": "pending" }),
    )
    .await;
    assert!(sheet.image.is_some() && !sheet.structured);
    let summary = sheet.json.clone().expect("summary");
    count(&summary);
    let names: Vec<String> = summary["cells"]
        .as_array()
        .expect("cells")
        .iter()
        .filter_map(|c| c["name"].as_str().map(str::to_owned))
        .collect();
    assert!(names.len() > 40, "{summary}");
    assert!(names.iter().any(|n| n == "zero") && names.iter().any(|n| n == "Aacute"));

    // Approving them all is a mass change: one plan, then its commit.
    let review = call(
        &client,
        "glyph_review",
        json!({ "doc": doc, "base_rev": rev, "glyphs": names, "decision": "approve" }),
    )
    .await
    .error("APPROVAL_REQUIRED");
    count(&review);
    let reviewed = call(
        &client,
        "plan_commit",
        json!({ "plan_token": review["details"]["plan"]["plan_token"] }),
    )
    .await
    .ok();
    count(&reviewed);
    let rev = reviewed["rev"].as_u64().expect("rev");

    let ttf = root.join("specimen.ttf");
    let exported = call(
        &client,
        "export_font",
        json!({ "doc": doc, "base_rev": rev, "format": "ttf", "path": ttf }),
    )
    .await
    .ok();
    count(&exported);
    assert!(ttf.is_file());

    let checked = call(&client, "validate", json!({ "doc": doc })).await.ok();
    count(&checked);
    assert_eq!(checked["report"]["errors"], 0, "{checked}");
    let pending = checked["report"]["findings"]
        .as_array()
        .expect("findings")
        .iter()
        .filter(|f| f["check"] == "glyph.pending_review")
        .count();
    assert_eq!(pending, 0, "every glyph made was approved");

    assert_eq!(calls, 8);
    assert!(text_bytes < 24 * 1024, "{text_bytes} bytes of answers");
    close(client).await;
}

/// The glyph outlines of a document, by name, from `glyph_get` through the
/// command line.
fn outlines(root: &std::path::Path, doc: &std::path::Path, names: &[&str]) -> Vec<Value> {
    names
        .iter()
        .map(|name| {
            let out = Command::new(forma_bin())
                .current_dir(root)
                .args(["call", "glyph_get", "--doc-path"])
                .arg(doc)
                .args(["--args", &json!({ "glyph": name }).to_string()])
                .output()
                .expect("forma call");
            assert!(out.status.success(), "{out:?}");
            let v: Value = serde_json::from_slice(&out.stdout).expect("json");
            v["glyph"]["paths"].clone()
        })
        .collect()
}

#[test]
fn cli_font_from_image_matches_mcp_shape() {
    // The same operation from the command line twice, on two documents:
    // the result is deterministic and complete.
    let root = tempfile::tempdir().expect("tempdir");
    let image = copy_specimen(root.path(), "specimen.png");
    let mut docs = Vec::new();
    for name in ["one.forma", "two.forma"] {
        let doc = root.path().join(name);
        let new = Command::new(forma_bin())
            .current_dir(root.path())
            .args(["new", name, "--family", "Specimen"])
            .output()
            .expect("forma new");
        assert!(new.status.success(), "{new:?}");
        let args = json!({ "path": path_text(&image), "layout": ["ABCH", "OFMR"] });
        let out = Command::new(forma_bin())
            .current_dir(root.path())
            .args(["call", "font_from_image", "--save", "-y", "--doc-path"])
            .arg(&doc)
            .args(["--args", &args.to_string()])
            .output()
            .expect("forma call");
        assert!(out.status.success(), "{out:?}");
        let v: Value = serde_json::from_slice(&out.stdout).expect("json");
        assert_eq!(v["stages"][0]["counts"]["glyphs"], 8, "{v}");
        docs.push(doc);
    }
    let letters = [
        "A",
        "B",
        "C",
        "H",
        "O",
        "F",
        "M",
        "R",
        "zero",
        "comma",
        "acutecomb",
        "Aacute",
    ];
    assert_eq!(
        outlines(root.path(), &docs[0], &letters),
        outlines(root.path(), &docs[1], &letters)
    );
}
